pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        // Initialize the contract as the current test contract (which becomes the owner)
        // We do not need to fully initialize with real tokens; just verify the owner invariant.
        // The initialization is not required because the bug is in the pure logic of owner(),
        // but we call initializer to set a real owner.
        // Since the constructor is complex, we simply check the logic after a minimal setup.
        // However, ownable requires initialization; we call initialize with dummy addresses.
        // To avoid complex dependencies, we simply check the owner() logic directly.
        // We assume the contract is deployed but uninitialized; owner() still returns address(0) in reference,
        // but the bug returns caller. So we need a situation where _owner is set.
        // We can directly manipulate storage with vm.store to set _owner, but that is forbidden.
        // Instead, we use the initializer with a valid call and then check against a different caller.
        // We need a minimal setup: we use the test contract itself as deployer and call initialize.
        // The initialize expects many arguments; we pass address(0) for them because the test only cares about ownership.
        // Initialize might revert if some addresses are zero, so we use a try/catch.
        try c.initialize(
            IERC20(address(0)),
            IERC20(address(0)),
            IRewardRouterV2(address(0)),
            IGlpManager(address(0)),
            address(0),
            address(0)
        ) {
        } catch {
            // if initialization fails, we cannot test the owner property reliably.
            // But we assume it succeeds for the sake of testing the bug.
        }
        // Now, we prank as a different caller and call owner().
        address storedOwner = c.owner();
        vm.prank(caller);
        address returnedByCaller = c.owner();
        // The property: When called by a non-owner, the returned address must equal the stored owner.
        assertTrue(returnedByCaller == storedOwner);
    }
}

