pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address pranker) public {
        // Assume pranker is the current owner so we can call transferOwnership
        // The fuzzer may pick any addresses; we require that the initial owner is pranker,
        // but since setUp() doesn't set an owner, we first need to make someone the owner.
        // We can initialize the contract with a known owner and then transfer ownership.
        // However, initialize is needed first. Let's use a simple scenario:
        // The fuzzer provides newOwner. We'll first initialize the contract with some valid addresses.
        // For the purpose of this test, we need to call transferOwnership. The owner must be set.
        // The simplest way without hardcoding is to let the fuzzer pick an initialOwner, call initialize
        // with that initialOwner, and then from that initialOwner call transferOwnership.
        vm.assume(pranker != address(0));
        vm.assume(newOwner != pranker);
        // Dummy addresses for initialization parameters that don't affect transferOwnership logic
        address dummy = address(uint160(uint256(keccak256(abi.encodePacked(pranker)))));
        // Avoid duplicates
        if (dummy == address(0) || dummy == pranker || dummy == newOwner) {
            dummy = address(uint160(uint256(keccak256(abi.encodePacked(dummy, "salt")))));
        }
        // Initialize the contract with pranker as the owner (via _keeper parameter, but Ownable_init sets owner to msg.sender)
        // Since initialize is initializer, we must call it from a non-zero address. We'll prank as pranker.
        vm.startPrank(pranker);
        // Need to provide valid IERC20 interfaces etc. They can be arbitrary addresses since transferOwnership doesn't use them.
        c.initialize(
            IERC20(dummy),
            IERC20(dummy),
            IRewardRouterV2(dummy),
            IGlpManager(dummy),
            dummy,
            pranker
        );
        // Now pranker is the owner. Call transferOwnership with newOwner.
        bool ok = true;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();
        // The property: if the call succeeded (did not revert), then the new owner must be non-zero.
        // In the correct contract, transferOwnership rejects zero address, so it either reverts
        // or succeeds with a non-zero owner. The buggy version allows zero address without revert,
        // making owner() zero after success.
        assertTrue(!ok || c.owner() != address(0), "Successful transferOwnership set owner to zero");
    }
}

